import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 032: sheet metal hole patterns. Generated by tools/fixtures/gen-batch-032.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function bodyCounts(context is Context) returns map
{
    const all = qEverything(EntityType.BODY);
    return { "solids" : evaluateQueryCount(context, qBodyType(all, BodyType.SOLID)),
             "active" : evaluateQueryCount(context, qActiveSheetMetalFilter(all, ActiveSheetMetal.YES)) };
}

// sheet-metal-pattern: a hole-feature hole's faces patterned 3 times, 10 mm apart
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    const pts1 = newSketchOnPlane(context, id + "pts1", { "sketchPlane" : plane(vector(0, 0, 2) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skPoint(pts1, "p1", { "position" : vector(8, 15) * millimeter });
    skSolve(pts1);
    hole(context, id + "hole1", { "locations" : qOwnedByBody(qBodyType(qCreatedBy(id + "pts1", EntityType.BODY), BodyType.POINT), EntityType.VERTEX), "scope" : qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), "style" : HoleStyle.SIMPLE, "holeDiameter" : 4 * millimeter, "endStyle" : HoleEndStyle.THROUGH });
    const dirX = newSketchOnPlane(context, id + "dirX", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(dirX, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(dirX);
    linearPattern(context, id + "pattern1", { "patternType" : PatternType.FACE, "faces" : qCreatedBy(id + "hole1", EntityType.FACE), "directionOne" : qCreatedBy(id + "dirX", EntityType.EDGE), "distance" : 10 * millimeter, "instanceCount" : 3, "oppositeDirection" : false });
    return { "counts" : bodyCounts(context) };
}

